import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Аукционы","description":"","frontmatter":{"pageId":"players/auctions","contentRevision":1},"headers":[],"relativePath":"ru/players/auctions.md","filePath":"ru/players/auctions.md"}'),o={name:"ru/players/auctions.md"};function l(s,a,n,c,d,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="аукционы" tabindex="-1">Аукционы <a class="header-anchor" href="#аукционы" aria-label="Permalink to &quot;Аукционы&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Выбери предметы, начальную цену и длительность. Аукцион принимает только предметы, не пешек. До первой ставки продавец может отменить его. Покупатель делает ставку из кошелька: вся текущая сумма резервируется, при перебитой ставке предыдущая сумма возвращается.</p><p>При завершении победитель получает товар посылкой, продавец — выручку с учётом комиссии. Если ставка поступила в последние 30 секунд, срок продлевается на 30 секунд, но всего не более чем на 5 минут. Обнови список, чтобы увидеть актуальный конец.</p><p>Офлайн-продавец не препятствует завершению. При заморозке расчёт ждёт разрешения; администратор может отменить проблемный аукцион.</p><h3 id="ставка-и-выкуп" tabindex="-1">Ставка и выкуп <a class="header-anchor" href="#ставка-и-выкуп" aria-label="Permalink to &quot;Ставка и выкуп&quot;">​</a></h3><p>В окне экономики открой вкладку аукционов. При создании выбери вещи, стартовую цену, срок в часах и необязательную цену выкупа (0 отключает выкуп). Подтверди публикацию и дождись сохранения/передачи вещей в escrow. Для покупки обнови список и проверь предметы и текущую цену: обычная ставка резервирует кошелёк и ждёт окончания. <strong>Выкуп</strong> по заданной продавцом цене завершает торги сразу; проверь посылку победителя и остаток кошелька. При недостатке серебра сначала пополни кошелёк, не отправляй продавцу отдельный перевод в обход аукциона.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>API допускает 60 секунд–30 дней, игровой интерфейс — 1–720 часов. Сброс/архивирование отменяют связанное эскроу. Не рассчитывай на ручную отмену продавцом после первой ставки.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./../admins/gameplay-policy">Игровая политика сервера</a></li></ul>',12)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
